SELECT '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'A1.1', 9, 'Possessive articles (mein, dein, sein …)', 'Possessivartikel: mein, dein, sein …', 'possessive-articles', 'Learn mein, dein, sein, ihr, unser, euer and Ihr, the possessive articles that take the same endings as ein — and how to avoid the #1 learner mistake of matching the ending to the owner instead of the noun.', 'Lerne mein, dein, sein, ihr, unser, euer und Ihr — die Possessivartikel mit den gleichen Endungen wie ein — und vermeide den häufigsten Fehler: die Endung richtet sich nach dem Nomen, nicht nach dem Besitzer.', 20, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['indefinite-articles','personal-pronouns']::text[], ARRAY['indefinite-articles','nouns-gender','verb-haben']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid);

