SELECT 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'A1.1', 11, 'Yes/no questions (Kommst du aus Italien?)', 'Ja/Nein-Fragen: Kommst du aus Italien?', 'yes-no-questions', 'Turn statements into yes/no questions by moving the verb to the front, and answer them with ja or nein.', 'Verwandle Aussagen in Ja/Nein-Fragen, indem du das Verb an den Satzanfang stellst, und antworte mit ja oder nein.', 20, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['verb-sein','present-tense-regular']::text[], ARRAY['question-words','basic-sentence-structure','separable-verbs-intro','time-and-dates']::text[]
