-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd2ea6b14-997a-57ff-a8ed-2406fb92f713'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'introduction', 'Possessive Articles Introduction', 'Einführung: Possessivartikel', '{"hook_de":"Du kennst ein und eine. Jetzt lernst du mein, dein, sein... (= my, your, his...).","hook_en":"You know ein and eine (a/an). Now meet mein, dein, sein... (= my, your, his...). They take the SAME endings as ein!","scenario_en":"Use a possessive article to say whose thing it is: my brother, your car, her key.","preview_note_en":"mein, dein, sein... take the same endings as ein: no ending for der/das-words, -e for die-words and the plural.","preview_highlight":"mein, meine, mein, meine","why_it_matters_en":"You need this to talk about your family and your things — and other people''s — every day.","preview_example_de":"mein Bruder, meine Schwester, mein Kind","preview_example_en":"my brother, my sister, my child","german_difference_en":"sein and seine both mean his (or its) — the ending depends on the noun''s gender, not on the owner. Sein Schwester is wrong; it must be seine Schwester, because Schwester is feminine.","english_comparison_en":"English has one word per owner: my, your, his, her, our, your, their. It never changes for the noun. German changes the ending to match the noun''s gender: mein Bruder, meine Schwester — same owner (I), different endings."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd2ea6b14-997a-57ff-a8ed-2406fb92f713'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '88a453b6-41ec-5e05-b35d-0194db3a0e5c'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'table', 'Possessive Articles: All Forms', 'Possessivartikel: Alle Formen', '{"rows":[["ich (I)","mein","meine","mein","meine"],["du (you)","dein","deine","dein","deine"],["er (he)","sein","seine","sein","seine"],["sie (she)","ihr","ihre","ihr","ihre"],["es (it)","sein","seine","sein","seine"],["wir (we)","unser","unsere","unser","unsere"],["ihr (you all)","euer","eure","euer","eure"],["sie (they)","ihr","ihre","ihr","ihre"],["Sie (you, formal)","Ihr","Ihre","Ihr","Ihre"]],"type":"case_table","headers":["Owner","maskulin (der)","feminin (die)","neutral (das)","Plural"],"highlight_row":-1,"description_de":"Possessivartikel bekommen die gleichen Endungen wie ein: keine Endung bei der/das-Wörtern, -e bei die-Wörtern und im Plural.","description_en":"Possessive articles take the same endings as ein: no ending for der/das-words, -e for die-words and the plural."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Das ist sein Schwester.","correct":"Das ist seine Schwester.","explanation_de":"Schwester ist feminin → seine. Das Geschlecht des Besitzers (er) spielt keine Rolle.","explanation_en":"Schwester is feminine, so the possessive needs -e: seine. The owner''s gender (he) does not matter here."},{"wrong":"Das ist meine Bruder.","correct":"Das ist mein Bruder.","explanation_de":"Bruder ist maskulin → mein, nicht meine.","explanation_en":"Bruder is masculine, so the possessive has no ending: mein, not meine."},{"wrong":"Wie ist ihr Name?","correct":"Wie ist Ihr Name?","explanation_de":"Zu einem Fremden: Ihr groß. Kleines ihr bedeutet her oder their.","explanation_en":"To a stranger (formal): Ihr is capitalized. Lowercase ihr means her or their."},{"wrong":"Wie heißt euere Mutter?","correct":"Wie heißt eure Mutter?","explanation_de":"euer verliert das e vor einer Endung: eure, nicht euere.","explanation_en":"euer drops its e before an ending: eure, not euere."}]'::jsonb, 'Same endings as ein: nothing for mein/dein/sein..., -e for die-words and plural. Only the front part changes for the owner!', 'Gleiche Endungen wie ein: nichts bei maskulin/neutral, -e bei feminin und Plural. Nur der Wortanfang wechselt mit dem Besitzer!', NULL, NULL, 'The ending always matches the NOUN''s gender, not the owner''s gender. sein Schwester is always wrong — Schwester is feminine, so it is always seine Schwester, even though the owner (er) is male.', 'Die Endung richtet sich immer nach dem Genus des Nomens, nicht nach dem Besitzer. Seine Schwester ist richtig, auch wenn der Besitzer (er) männlich ist.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '88a453b6-41ec-5e05-b35d-0194db3a0e5c'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7bc0f7ac-9818-587d-a6da-717cf9937a0d'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'table', 'sein, ihr, or Ihr? Who Owns It', 'sein, ihr oder Ihr? Wer ist der Besitzer?', '{"rows":[["sein","er (he)","his","Das ist sein Auto. (his car)"],["sein","es (it)","its","Das Kind hat sein Buch. (its book)"],["ihr","sie (she)","her","Das ist ihr Auto. (her car)"],["ihr","sie (they)","their","Das ist ihr Auto. (their car)"],["Ihr","Sie (formal you)","your (formal)","Ist das Ihr Auto? (your car, formal)"]],"type":"case_table","headers":["Form","Owner","English","Example"],"highlight_row":-1,"description_de":"sein = Besitz von er/es. ihr = Besitz von sie (Einzahl) oder sie (Plural). Ihr (großgeschrieben) = Besitz von Sie (Höflichkeitsform).","description_en":"sein = belongs to him/it. ihr = belongs to her OR to them (plural). Ihr (capital) = belongs to Sie, the formal you."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'sein → for er and es. ihr (small) → for sie (she) and sie (they). Ihr (capital, always!) → for Sie, the polite you.', 'sein → für er und es. ihr (klein) → für sie (Einzahl) und sie (Plural). Ihr (immer groß!) → für Sie, die Höflichkeitsform.', 'Ihr is always capitalized, in every position in the sentence — not only at the start.', 'Ihr wird immer großgeschrieben, an jeder Stelle im Satz — nicht nur am Satzanfang.', 'Only capitalization tells Ihr (your, formal) apart from ihr (her/their) in writing — in speech, context tells you which one is meant.', 'Nur die Großschreibung unterscheidet Ihr (Höflichkeitsform) von ihr (her/their) in der Schrift — beim Sprechen hilft der Kontext.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7bc0f7ac-9818-587d-a6da-717cf9937a0d'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '4c8d285c-f6d1-5b6b-b8eb-f001436a4f96'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'pattern', 'How to Choose the Right Possessive Form', 'So wählst du die richtige Possessivform', '{"type":"steps","steps":[{"step":1,"title_de":"Wer ist der Besitzer? Wähle das Wort.","title_en":"Who is the owner? Choose the word.","detail_de":"ich → mein, du → dein, er/es → sein, sie → ihr, wir → unser, ihr → euer, Sie → Ihr.","detail_en":"ich → mein, du → dein, er/es → sein, sie (she/they) → ihr, wir → unser, ihr → euer, Sie (formal) → Ihr. This is the owner, not the noun."},{"step":2,"title_de":"Welches Genus hat das Nomen? Wähle die Endung.","title_en":"What gender is the noun? Choose the ending.","detail_de":"der-Wort oder das-Wort → keine Endung. die-Wort oder Plural → -e.","detail_en":"der-word or das-word → no ending. die-word or plural → add -e. The noun''s gender decides the ending, not the owner''s gender."},{"step":3,"title_de":"Setze Wort + Endung zusammen.","title_en":"Put word + ending together.","detail_de":"sein (er) + Schwester (die-Wort) → seine Schwester.","detail_en":"sein (owner: er) + Schwester (a die-word) → seine Schwester. mein (owner: ich) + Bruder (a der-word) → mein Bruder."}],"description_en":"Two questions, two choices: who owns it, then what gender is the noun.","description_de":"Zwei Fragen, zwei Entscheidungen: Wer ist der Besitzer, dann welches Genus hat das Nomen."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '4c8d285c-f6d1-5b6b-b8eb-f001436a4f96'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '507e0574-bd50-52d4-97d9-aab56bf02023'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'tip', 'After haben, the Masculine Possessive Changes', 'Nach haben verändert sich der maskuline Possessivartikel', '{"content_de":"Vorschau auf den Akkusativ (A1.2): Nach haben bekommt der Possessivartikel vor einem maskulinen Nomen die Endung -en: Ich habe meinen Bruder gern. Hast du deinen Schlüssel?","content_en":"A preview of the Akkusativ case (you''ll learn this properly in A1.2): after haben, a masculine possessive takes -en instead of no ending. Ich habe meinen Bruder gern. (I like my brother.) Hast du deinen Schlüssel? (Do you have your key?) Only masculine changes — feminine, neuter and plural stay the same after haben."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '507e0574-bd50-52d4-97d9-aab56bf02023'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd3927868-4ea3-5ce9-bf4e-60947627ec27'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'warning', 'sein (his) vs. sein (to be) — Not the Same Word!', 'sein (Possessivartikel) vs. sein (Verb) — nicht dasselbe!', '{"content_de":"Achtung: sein ist zweimal wichtig! 1) sein = Possessivartikel (his/its): Das ist sein Auto. 2) sein = das Verb sein im Infinitiv, wie in ich bin, du bist, er ist. Zwei verschiedene Wörter, gleiche Buchstaben!","content_en":"Watch out: sein is two different words that look the same! 1) sein = possessive article (his/its): Das ist sein Auto. (That is his car.) 2) sein = the infinitive of the verb to be, the one behind ich bin, du bist, er ist. Same letters, completely different job — check the sentence to see which one you have."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd3927868-4ea3-5ce9-bf4e-60947627ec27'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '91ca9313-d277-5bb5-ab19-82267f8865c3'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["mein, dein, sein, ihr, unser, euer and Ihr take the same endings as ein: nothing for der/das-words, -e for die-words and the plural.","The ending matches the NOUN''s gender, never the owner''s gender: seine Schwester (Schwester is feminine), even though the owner is male.","sein = his or its (owner: er, es). ihr = her (sie, singular) OR their (sie, plural) — context decides.","Ihr, always capitalized, = your (formal, owner: Sie).","euer loses its e before an ending: euer → eure, not euere.","Preview: after haben, a masculine noun''s possessive takes -en (meinen Bruder) — the full Akkusativ rule comes in A1.2."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '91ca9313-d277-5bb5-ab19-82267f8865c3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '3f6ae7cb-cf3b-5e50-a487-0bcd433445b5'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'introduction', 'Separable Verbs Introduction', 'Einführung: Trennbare Verben', '{"hook_de":"Manche Verben haben zwei Teile: auf-stehen, an-rufen, ein-kaufen. Der erste Teil — das Präfix — wandert ans Satzende!","hook_en":"Some German verbs split into two parts: aufstehen (get up), anrufen (call), einkaufen (shop). In a sentence, the prefix jumps to the very end!","scenario_en":"You use separable verbs every day: Ich stehe um 7 Uhr auf. Ich rufe meine Mutter an. Wir kaufen heute ein.","preview_note_en":"The prefix (auf-, an-, ein-, mit-, zu-, aus-, ab-...) is always stressed, and in a sentence it moves to the end.","preview_highlight":"stehe … auf","why_it_matters_en":"Separable verbs are everywhere in daily routines and phone calls — exactly what the exam asks about.","preview_example_de":"Ich stehe um 7 Uhr auf.","preview_example_en":"I get up at 7 o''clock.","german_difference_en":"The infinitive aufstehen looks like one word, but in a normal sentence it splits: the stem (steh-) stays in position 2, and auf jumps to the very end of the sentence.","english_comparison_en":"English ''get up'' stays together: I get up at 7. German splits it: Ich stehe um 7 Uhr auf — the prefix auf goes last."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '3f6ae7cb-cf3b-5e50-a487-0bcd433445b5'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c14b880d-6a50-5467-af67-5faee6146303'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'table', 'The Sentence Bracket (Satzklammer)', 'Die Satzklammer', '{"type":"case_table","headers":["Position 1","Konjugiertes Verb","Mitte","Präfix (Ende)"],"rows":[["Ich","stehe","um 7 Uhr","auf"],["Du","rufst","deine Mutter","an"],["Wir","kaufen","heute","ein"],["Ihr","kommt","um 8 Uhr","mit"],["Er","räumt","sein Zimmer","auf"],["—","Stehst","du um 7 Uhr","auf"]],"highlight_row":-1,"description_de":"Der konjugierte Stamm steht auf Position 2, das Präfix wandert ans Satzende. In einer Ja/Nein-Frage steht das konjugierte Verb an erster Stelle (kein Subjekt in Position 1), aber das Präfix bleibt trotzdem am Ende.","description_en":"The conjugated stem sits in position 2, and the prefix always moves to the very end of the sentence. In a yes/no question, the conjugated verb stands first instead (last row: no subject in position 1) — but the prefix still ends the sentence."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich aufstehe um 7 Uhr.","correct":"Ich stehe um 7 Uhr auf.","explanation_de":"Der Infinitiv bleibt im Satz nicht zusammen — konjugiere den Stamm und schicke das Präfix ans Ende.","explanation_en":"The infinitive doesn''t stay together in a sentence — conjugate the stem and send the prefix to the end."},{"wrong":"Ich stehe auf um 7 Uhr.","correct":"Ich stehe um 7 Uhr auf.","explanation_de":"Das Präfix muss das letzte Wort sein, nach der Zeitangabe.","explanation_en":"The prefix must be the very last word, after the time phrase."},{"wrong":"Er anruft seine Mutter.","correct":"Er ruft seine Mutter an.","explanation_de":"Nur der Stamm wird konjugiert (ruft); das Präfix an bleibt getrennt und steht am Ende.","explanation_en":"Only the stem is conjugated (ruft); the prefix an stays separate and goes to the end."}]'::jsonb, 'Stem in slot two, prefix out the door — like a sandwich around the sentence.', 'Stamm auf Platz zwei, Präfix ganz hinten — wie ein Sandwich um den Satz.', NULL, NULL, 'The conjugated stem and the prefix form a bracket (Satzklammer) around the rest of the sentence — the prefix is always the last word.', 'Der konjugierte Stamm und das Präfix bilden eine Klammer (Satzklammer) um den Satz — das Präfix ist immer das letzte Wort.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c14b880d-6a50-5467-af67-5faee6146303'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '2f2db2b4-0b8a-53c6-b864-384ec2f81ff0'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'table', 'Conjugating aufstehen and anrufen', 'Konjugation von aufstehen und anrufen', '{"type":"case_table","headers":["Pronomen","aufstehen","anrufen"],"rows":[["ich","stehe auf","rufe an"],["du","stehst auf","rufst an"],["er/sie/es","steht auf","ruft an"],["wir","stehen auf","rufen an"],["ihr","steht auf","ruft an"],["sie/Sie","stehen auf","rufen an"]],"highlight_row":-1,"description_de":"Der Stamm bekommt die normale Endung, die du schon kennst; das Präfix bleibt gleich und steht am Ende.","description_en":"The stem takes the normal ending you already know; the prefix never changes and always comes last."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '2f2db2b4-0b8a-53c6-b864-384ec2f81ff0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f6b22446-f563-54f9-930b-e28949aa82d6'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'pattern', 'How to Build a Separable-Verb Sentence', 'So baust du einen Satz mit trennbarem Verb', '{"type":"steps","steps":[{"step":1,"title_de":"Präfix finden","title_en":"Find the prefix","detail_de":"aufstehen → auf + stehen. Das Präfix ist der kleine Teil vor dem Verbstamm.","detail_en":"aufstehen → auf + stehen. The prefix is the small word attached to the front of the infinitive (auf-, an-, ein-, mit-, zu-, aus-, ab-)."},{"step":2,"title_de":"Stamm konjugieren","title_en":"Conjugate the stem","detail_de":"stehen konjugierst du wie gewohnt: ich stehe, du stehst, er steht.","detail_en":"Conjugate stehen exactly as you learned: ich stehe, du stehst, er steht — the prefix stays off to the side for now."},{"step":3,"title_de":"Präfix ans Ende schicken","title_en":"Send the prefix to the end","detail_de":"Das Präfix auf wandert ans Satzende: Ich stehe auf. Mit mehr Wörtern: Ich stehe um 7 Uhr auf.","detail_en":"Now put the prefix at the very end of the sentence: Ich stehe auf. Add more words in the middle: Ich stehe um 7 Uhr auf."}],"description_de":"Drei Schritte für jeden Satz mit trennbarem Verb.","description_en":"Three steps for every sentence with a separable verb."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f6b22446-f563-54f9-930b-e28949aa82d6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '4af6a191-ca14-5aa2-984d-11fce6b29201'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'tip', '12 Everyday Separable Verbs', '12 alltägliche trennbare Verben', '{"type":"verb_list","groups":[{"category_en":"Daily routine (Tagesablauf)","verbs":[{"de":"aufstehen","en":"to get up","example":"Ich stehe um 7 Uhr auf. (I get up at 7 o''clock.)"},{"de":"aufräumen","en":"to tidy up","example":"Er räumt sein Zimmer auf. (He tidies up his room.)"},{"de":"ausgehen","en":"to go out","example":"Wir gehen heute aus. (We''re going out today.)"},{"de":"zuhören","en":"to listen","example":"Er hört gut zu. (He listens well.)"}]},{"category_en":"Phone & appointments (Telefon & Termine)","verbs":[{"de":"anrufen","en":"to call","example":"Ich rufe meine Mutter an. (I call my mother.)"},{"de":"mitkommen","en":"to come along","example":"Kommst du mit? (Are you coming along?)"},{"de":"abholen","en":"to pick up","example":"Ich hole dich um 8 Uhr ab. (I''ll pick you up at 8 o''clock.)"},{"de":"ankommen","en":"to arrive","example":"Der Zug kommt um 9 Uhr an. (The train arrives at 9 o''clock.)"}]},{"category_en":"Shopping & at home (Einkaufen & Zuhause)","verbs":[{"de":"einkaufen","en":"to shop","example":"Ich kaufe heute ein. (I''m going shopping today.)"},{"de":"aufmachen","en":"to open","example":"Ich mache das Fenster auf. (I open the window.)"},{"de":"zumachen","en":"to close","example":"Er macht die Tür zu. (He closes the door.)"},{"de":"mitbringen","en":"to bring along","example":"Ich bringe die Kamera mit. (I bring the camera along.)"}]}],"description_en":"Twelve everyday separable verbs, grouped by theme — all with regular stems."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '4af6a191-ca14-5aa2-984d-11fce6b29201'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd15cbf28-d46f-5341-8f55-9aa92fdbc3e2'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'warning', 'The infinitive stays together — and two special verbs', 'Infinitiv bleibt zusammen — und zwei besondere Verben', '{"content_de":"Im Infinitiv bleibt das Präfix immer vorne: aufstehen, nicht stehenauf. Manche trennbaren Verben ändern zusätzlich den Stamm: fernsehen → du siehst fern; anfangen → er fängt an. Das lernst du bald genauer.","content_en":"In the infinitive, the prefix always stays at the front: aufstehen, never stehenauf. Some separable verbs also change their stem: fernsehen (to watch TV) → du siehst fern; anfangen (to start) → er fängt an. You will drill these two properly in a later lesson."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd15cbf28-d46f-5341-8f55-9aa92fdbc3e2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '6c30b283-6f93-5861-96ca-200b6d49afc3'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Separable verbs split: a prefix (auf-, an-, ein-, mit-, zu-, aus-, ab-) detaches from the stem in a sentence.","The conjugated stem stays in position 2; the prefix always moves to the very end of the sentence.","In yes/no questions, the stem moves first and the prefix still ends the sentence: Stehst du auf?","The infinitive stays one word: aufstehen, anrufen, einkaufen — never split.","With a time phrase, the prefix comes after it: Ich stehe um 7 Uhr auf.","fernsehen and anfangen also change their stem (du siehst fern, er fängt an) — more on that soon.","Twelve everyday separable verbs to know: aufstehen, anrufen, einkaufen, mitkommen, aufmachen, zumachen, aufräumen, mitbringen, ankommen, ausgehen, abholen, zuhören."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '6c30b283-6f93-5861-96ca-200b6d49afc3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9dcb877a-b36d-5224-8d15-2700e52df693'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'introduction', 'Yes/No Questions Introduction', 'Einführung: Ja/Nein-Fragen', '{"hook_de":"Du kennst schon Aussagesätze. Jetzt lernst du Fragen mit Ja oder Nein.","hook_en":"You already know how to make statements. Now learn how to ask a question that gets a simple ja or nein answer — by moving the verb to the very front.","scenario_en":"You need yes/no questions everywhere: at the Anmeldung, in a job interview, on the exam''s speaking test, and in everyday chat with friends.","preview_note_en":"Statement: Du kommst aus Italien. Question: just swap the first two words — Kommst du aus Italien?","preview_highlight":"Kommst du aus Italien?","why_it_matters_en":"The exam''s Sprechen Teil 2 is built entirely on asking and answering yes/no and information questions — this is a core speaking skill.","preview_example_de":"Du kommst aus Italien. → Kommst du aus Italien?","preview_example_en":"You come from Italy. → Do you come from Italy?","german_difference_en":"In English you add do/does to ask a question (Do you come...?). In German you don''t add anything — you simply move the verb itself to the front: Kommst du...?","english_comparison_en":"English needs a helper word: Do you come from Italy? German has no do — the main verb itself jumps to the front: Kommst du aus Italien?"}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9dcb877a-b36d-5224-8d15-2700e52df693'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '2628ee69-c13f-5c67-991a-3cb2b9b52b7b'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'table', 'Statement to Question', 'Aussage → Frage', '{"type":"case_table","headers":["Aussage","Ja/Nein-Frage","English"],"rows":[["Du bist müde.","Bist du müde?","Are you tired?"],["Du hast Zeit.","Hast du Zeit?","Do you have time?"],["Du kommst aus Italien.","Kommst du aus Italien?","Do you come from Italy?"],["Du arbeitest viel.","Arbeitest du viel?","Do you work a lot?"],["Du stehst früh auf.","Stehst du früh auf?","Do you get up early?"],["Sie wohnen in Berlin.","Wohnen Sie in Berlin?","Do you live in Berlin? (formal)"]],"highlight_row":-1,"description_de":"Verb an Position 1, Subjekt an Position 2 — der Rest bleibt gleich.","description_en":"The verb moves to position 1, the subject to position 2 — everything else stays the same."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Du kommst aus Italien?","correct":"Kommst du aus Italien?","explanation_de":"Bei geschriebenen Fragen steht das Verb an Position 1 — nicht nur ein Fragezeichen am Satzende.","explanation_en":"A written question needs the verb moved to position 1 — adding just a question mark to a statement is not enough."},{"wrong":"Kommst aus Italien du?","correct":"Kommst du aus Italien?","explanation_de":"Das Subjekt steht direkt nach dem Verb (Position 2), nicht am Satzende.","explanation_en":"The subject goes right after the verb, in position 2 — not at the end of the sentence."},{"wrong":"Sind Sie Frau Meier? — Ja, ich bin.","correct":"Ja, ich bin Frau Meier.","explanation_de":"Die Kurzantwort wiederholt die ganze Aussage, nicht nur Ja/Nein + Verb.","explanation_en":"A short answer repeats the whole statement — Ja/Nein plus verb alone is incomplete."}]'::jsonb, 'Statement: Du kommst... Question: swap the first two words → Kommst du...?', 'Aussage: Du kommst... Frage: die ersten zwei Wörter tauschen → Kommst du...?', 'With Sie, the verb form doesn''t change — Sie wohnen (statement) becomes Wohnen Sie...? (question), same verb form, just moved to the front.', 'Bei Sie ändert sich die Verbform nicht — aus Sie wohnen wird Wohnen Sie...?, gleiche Verbform, nur an den Anfang gestellt.', 'In a yes/no question the verb always takes position 1 and the subject takes position 2 — swapped from the statement order.', 'In einer Ja/Nein-Frage steht das Verb immer an Position 1 und das Subjekt an Position 2 — vertauscht zur Aussage.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '2628ee69-c13f-5c67-991a-3cb2b9b52b7b'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '321f16f1-62d9-5d45-91a5-3a467b09b1cb'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'table', 'Short Answers', 'Kurzantworten', '{"type":"case_table","headers":["Frage","Ja-Antwort","Nein-Antwort"],"rows":[["Kommst du aus Italien?","Ja, ich komme aus Italien.","Nein, ich komme aus Spanien."],["Bist du müde?","Ja, ich bin müde.","Nein, ich bin wach."],["Hast du Zeit?","Ja, ich habe Zeit.","Nein, ich habe Arbeit."],["Sind Sie Frau Meier?","Ja, ich bin Frau Meier.","Nein, ich bin Frau Schmidt."],["Stehst du früh auf?","Ja, ich stehe früh auf.","Nein, ich stehe spät auf."],["Sprechen Sie Englisch?","Ja, ich spreche Englisch.","Nein, ich spreche Deutsch."]],"highlight_row":-1,"description_de":"Die Kurzantwort wiederholt die Aussage — nicht nur Ja oder Nein allein.","description_en":"A short answer repeats the statement — never just Ja or Nein alone."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '321f16f1-62d9-5d45-91a5-3a467b09b1cb'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '19e2ebda-8b98-5605-b22a-9cca30817d93'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'table', 'W-Question vs Yes/No Question', 'W-Frage vs. Ja/Nein-Frage', '{"type":"case_table","headers":["W-Frage","Ja/Nein-Frage","English"],"rows":[["Wie heißt du?","Heißt du Anna?","Is your name Anna?"],["Wo wohnst du?","Wohnst du in Köln?","Do you live in Cologne?"],["Woher kommst du?","Kommst du aus Italien?","Do you come from Italy?"],["Was trinkst du?","Trinkst du Kaffee?","Do you drink coffee?"],["Wer ist das?","Ist das Anna?","Is that Anna?"]],"highlight_row":-1,"description_de":"Eine W-Frage beginnt mit einem Fragewort und fragt nach Information. Eine Ja/Nein-Frage beginnt mit dem Verb und fragt nach Ja oder Nein.","description_en":"A W-question starts with a question word and asks for information. A yes/no question starts with the verb and asks for ja or nein."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '19e2ebda-8b98-5605-b22a-9cca30817d93'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '375c3450-eba2-56ae-b7d1-d5b62d7a99e7'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'pattern', 'How to Build a Yes/No Question', 'So baust du eine Ja/Nein-Frage', '{"type":"steps","steps":[{"step":1,"title_de":"Finde das konjugierte Verb","title_en":"Find the conjugated verb","detail_de":"In der Aussage steht das Verb an Position 2. Du kommst aus Italien. → Verb = kommst.","detail_en":"In the statement, the conjugated verb sits in position 2. Du kommst aus Italien. → the verb is kommst."},{"step":2,"title_de":"Stelle das Verb an den Anfang","title_en":"Put the verb first","detail_de":"Das Verb wandert an Position 1: Kommst...","detail_en":"Move the verb to position 1: Kommst..."},{"step":3,"title_de":"Subjekt an Position 2","title_en":"Subject goes second","detail_de":"Das Subjekt steht direkt danach: Kommst du...","detail_en":"The subject follows right after the verb: Kommst du..."},{"step":4,"title_de":"Die Stimme steigt","title_en":"Your voice rises","detail_de":"Am Ende einer Ja/Nein-Frage steigt die Stimme: Kommst du aus Italien? ↗","detail_en":"At the end of a yes/no question, the pitch of your voice rises — unlike a statement, which falls: Kommst du aus Italien? ↗"}],"description_de":"Vier einfache Schritte, um jede Aussage in eine Ja/Nein-Frage zu verwandeln.","description_en":"Four simple steps to turn any statement into a yes/no question."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '375c3450-eba2-56ae-b7d1-d5b62d7a99e7'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '354d03cd-0b56-5162-9028-a2a619e00d27'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'tip', 'A Preview: doch', 'Ein Ausblick: doch', '{"content_de":"doch = ja bei einer negativen Frage. Beispiel: Kommst du nicht? — Doch!","content_en":"doch is the special answer used to contradict a negative question — it means \"yes, I do!\". Example: Kommst du nicht? — Doch! (You''ll learn negation properly later.)"}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '354d03cd-0b56-5162-9028-a2a619e00d27'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '35a9538b-d121-529b-ad72-0918ade32eb3'::uuid, 'f29b3240-b144-5f4f-8c58-a502c293b01d'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["To ask a yes/no question, move the verb to position 1 and the subject to position 2: Du kommst... → Kommst du...?","Your voice rises at the end of a yes/no question.","With Sie, the verb form stays the same as in the statement: Sie wohnen... → Wohnen Sie...?","With separable verbs, the stem moves to position 1 and the prefix stays at the end: Stehst du früh auf?","Short answers repeat the statement: Ja, ich komme aus Italien. / Nein, ich komme aus Spanien.","A written question always needs verb-subject order — a question mark alone is not enough.","doch is the special way to say \"yes!\" when contradicting a negative question — more on this later."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '35a9538b-d121-529b-ad72-0918ade32eb3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'b0db0498-139d-556d-a83c-29020de69693'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'introduction', 'Time and Dates Introduction', 'Einführung: Uhrzeit und Datum', '{"hook_de":"Wie spät ist es? Welcher Tag ist heute? Wann hast du Geburtstag? Diese Fragen brauchst du jeden Tag!","hook_en":"What time is it? What day is it? When is your birthday? You need these questions every single day — and the exam tests exactly this.","scenario_en":"You hear an announcement: ''Der Zug kommt um 14:30 Uhr an.'' You fill in a form: ''Geburtsdatum: ___''. Someone asks: ''Wann stehst du auf?'' All of this is time and dates.","preview_note_en":"German has two ways to say time: official (14:30 = vierzehn Uhr dreißig) and colloquial (2:30 = halb drei). Halb drei is the classic trap — it means 2:30, not 3:30!","preview_highlight":"halb drei, Viertel nach, am Montag, im Mai","why_it_matters_en":"The exam needs this exact vocabulary: train times in Hören, your birthdate in Schreiben, and your daily routine in Sprechen.","preview_example_de":"Es ist halb drei. Der Kurs ist am Montag. Ich habe am dritten Mai Geburtstag.","preview_example_en":"It is 2:30. The course is on Monday. My birthday is on May 3rd.","german_difference_en":"German has two time registers: official 24-hour time for schedules (vierzehn Uhr dreißig) and colloquial 12-hour time for everyday speech (halb drei). English speakers often misread halb drei as 3:30 — it actually means 2:30, halfway TO three.","english_comparison_en":"English says ''half past two'' (counting from 2:00), but German says ''halb drei'' (counting toward 3:00 — halfway to three). This reversed logic is the single biggest time-telling mistake for English speakers."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'b0db0498-139d-556d-a83c-29020de69693'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '98cd3eed-76f1-5c65-b448-2cdfeb683cca'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'table', 'Recap: Numbers 1–12 and Tens', 'Wiederholung: Zahlen 1–12 und Zehnerzahlen', '{"type":"case_table","headers":["Zahl","Deutsch"],"rows":[["1","eins"],["2","zwei"],["3","drei"],["4","vier"],["5","fünf"],["6","sechs"],["7","sieben"],["8","acht"],["9","neun"],["10","zehn"],["11","elf"],["12","zwölf"],["20","zwanzig"],["30","dreißig"],["40","vierzig"],["50","fünfzig"],["60","sechzig"],["70","siebzig"],["80","achtzig"],["90","neunzig"],["100","hundert"]],"highlight_row":-1,"description_de":"Du kennst diese Zahlen schon — du brauchst sie jetzt für die Uhrzeit und das Datum.","description_en":"You already know these numbers — now you need them for telling the time and the date."}'::jsonb, 0, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '98cd3eed-76f1-5c65-b448-2cdfeb683cca'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5041c7d4-c8c5-599f-852d-0684cbb7c3ed'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'table', 'Official vs. Colloquial Time', 'Offizielle vs. umgangssprachliche Uhrzeit', '{"type":"case_table","headers":["Digital","Offiziell","Umgangssprachlich","English"],"rows":[["2:30","zwei Uhr dreißig","halb drei","2:30 (halfway TO three)"],["2:15","zwei Uhr fünfzehn","Viertel nach zwei","2:15 (quarter past two)"],["2:45","zwei Uhr fünfundvierzig","Viertel vor drei","2:45 (quarter to three)"],["14:30","vierzehn Uhr dreißig","halb drei","2:30 pm (24-hour vs. 12-hour)"],["8:05","acht Uhr fünf","fünf nach acht","8:05 (five past eight)"],["12:00","zwölf Uhr","zwölf Uhr","12:00 (noon)"],["0:00","null Uhr","Mitternacht","0:00 (midnight)"],["18:20","achtzehn Uhr zwanzig","zwanzig nach sechs","6:20 pm (twenty past six)"]],"highlight_row":-1,"description_de":"Wie spät ist es? / Wie viel Uhr ist es? Offiziell: 24-Stunden-System (Bahn, Fernsehen, Termine). Umgangssprachlich: 12-Stunden-System mit halb/Viertel/nach/vor.","description_en":"Wie spät ist es? / Wie viel Uhr ist es? = What time is it? Official time uses the 24-hour clock (trains, TV, appointments). Colloquial time uses the 12-hour clock with halb/Viertel/nach/vor."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Es ist halb drei Uhr. (gemeint: 3:30)","correct":"Es ist halb drei. (= 2:30)","explanation_de":"halb drei bedeutet 2:30, nicht 3:30 — halb + die NÄCHSTE Stunde.","explanation_en":"halb drei means 2:30, not 3:30 — halb + the NEXT hour, i.e. halfway TO three."},{"wrong":"Der Kurs ist um Montag.","correct":"Der Kurs ist am Montag.","explanation_de":"Wochentage benutzen am. um ist nur für Uhrzeiten.","explanation_en":"Weekdays use am, not um. um is only for clock times (um acht Uhr)."},{"wrong":"Mein Geburtstag ist am fünf Mai.","correct":"Mein Geburtstag ist am fünften Mai.","explanation_de":"Nach am braucht das Datum die Ordnungszahl mit -en: am fünften.","explanation_en":"After am, the date needs the ordinal number with the -en ending: am fünften, not the plain number fünf."},{"wrong":"Es ist halb drei Uhr.","correct":"Es ist halb drei.","explanation_de":"halb, Viertel nach und Viertel vor stehen nie zusammen mit Uhr.","explanation_en":"halb, Viertel nach and Viertel vor never combine with the word Uhr — just say halb drei, not halb drei Uhr."}]'::jsonb, 'halb + the NEXT hour = the half hour before it. halb drei = 2:30 (on the way to 3), never 3:30!', 'halb + die NÄCHSTE Stunde. halb drei = 2:30, niemals 3:30!', 'Use official time (Uhr + hour + minutes, 24-hour) for schedules, trains, announcements and formal writing. Use colloquial time (12-hour, halb/Viertel/nach/vor) in everyday spoken German.', 'Benutze die offizielle Zeit (Uhr + Stunde + Minuten, 24-Stunden) für Fahrpläne, Züge, Durchsagen und formelle Texte. Benutze die Umgangssprache (12-Stunden, halb/Viertel/nach/vor) im Alltag beim Sprechen.', 'German colloquial time looks BACKWARDS to English speakers: halb drei counts UP toward drei, so it means 2:30, not 3:30.', 'halb drei zählt auf die nächste Stunde zu — deshalb ist halb drei 2:30, nicht 3:30.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5041c7d4-c8c5-599f-852d-0684cbb7c3ed'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd995a199-55b8-540c-8e75-bb3e131554c5'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'table', 'Wann? — am, um, im', 'Wann? — am, um, im', '{"type":"case_table","headers":["Frage","Antwort","Präposition"],"rows":[["Wann hast du Deutschkurs?","Am Montag.","am + Wochentag"],["Um wie viel Uhr beginnt der Kurs?","Um neun Uhr.","um + Uhrzeit"],["Wann hast du Geburtstag?","Im Mai.","im + Monat"],["Wann trinkst du Kaffee?","Am Morgen.","am + Tageszeit"],["Wann hast du frei?","Am Wochenende.","am + Wochenende"],["Wann bist du zu Hause?","In der Nacht.","in + der Nacht (Ausnahme!)"]],"highlight_row":5,"description_de":"am + Wochentag, am + Tageszeit, am + Wochenende. um + Uhrzeit. im + Monat. Ausnahme: in der Nacht (nicht am Nacht!).","description_en":"am + weekday, am + time of day, am + weekend. um + clock time. im + month. Exception: in der Nacht — not am Nacht!"}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd995a199-55b8-540c-8e75-bb3e131554c5'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '375a5329-f98f-5c82-ba28-7700c87d7da0'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'table', 'Weekdays and Times of Day', 'Wochentage und Tageszeiten', '{"type":"case_table","headers":["Deutsch","English","Beispiel"],"rows":[["Montag","Monday","Am Montag habe ich Deutschkurs."],["Dienstag","Tuesday","Am Dienstag arbeite ich."],["Mittwoch","Wednesday","Am Mittwoch kaufe ich ein."],["Donnerstag","Thursday","Am Donnerstag räume ich auf."],["Freitag","Friday","Am Freitag komme ich an."],["Samstag","Saturday","Am Samstag stehe ich spät auf."],["Sonntag","Sunday","Am Sonntag rufe ich meine Mutter an."],["am Morgen","in the morning","Am Morgen trinke ich Kaffee."],["am Vormittag","in the late morning","Am Vormittag arbeite ich."],["am Mittag","at midday","Am Mittag mache ich eine Pause."],["am Nachmittag","in the afternoon","Am Nachmittag lerne ich Deutsch."],["am Abend","in the evening","Am Abend höre ich Musik."],["in der Nacht","at night","In der Nacht bin ich zu Hause."]],"highlight_row":-1,"description_de":"Die sieben Wochentage und die sechs Tageszeiten. Alle benutzen am — außer in der Nacht!","description_en":"The seven weekdays and the six times of day. All use am — except in der Nacht!"}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '375a5329-f98f-5c82-ba28-7700c87d7da0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '26660293-a896-5db5-8ee3-72a081b9f501'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'table', 'The Months', 'Die Monate', '{"type":"case_table","headers":["Monat","Beispiel","English"],"rows":[["Januar","im Januar","January"],["Februar","im Februar","February"],["März","im März","March"],["April","im April","April"],["Mai","im Mai","May"],["Juni","im Juni","June"],["Juli","im Juli","July"],["August","im August","August"],["September","im September","September"],["Oktober","im Oktober","October"],["November","im November","November"],["Dezember","im Dezember","December"]],"highlight_row":-1,"description_de":"Die zwölf Monate. Wann? — im + Monat (im Januar, im Mai, im Dezember).","description_en":"The twelve months. Wann? — im + month (im Januar, im Mai, im Dezember)."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '26660293-a896-5db5-8ee3-72a081b9f501'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'db4b344f-55c9-55ca-9358-733268fce5dc'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'table', 'Ordinal Numbers for Dates', 'Ordnungszahlen für das Datum', '{"type":"case_table","headers":["Zahl","der ___e (Datum)","am ___en (Wann?)","English"],"rows":[["1","erste","ersten","1st"],["2","zweite","zweiten","2nd"],["3","dritte","dritten","3rd"],["4","vierte","vierten","4th"],["5","fünfte","fünften","5th"],["6","sechste","sechsten","6th"],["7","siebte","siebten","7th"],["8","achte","achten","8th"],["9","neunte","neunten","9th"],["10","zehnte","zehnten","10th"],["11","elfte","elften","11th"],["12","zwölfte","zwölften","12th"],["13","dreizehnte","dreizehnten","13th"],["14","vierzehnte","vierzehnten","14th"],["15","fünfzehnte","fünfzehnten","15th"],["16","sechzehnte","sechzehnten","16th"],["17","siebzehnte","siebzehnten","17th"],["18","achtzehnte","achtzehnten","18th"],["19","neunzehnte","neunzehnten","19th"],["20","zwanzigste","zwanzigsten","20th"],["21","einundzwanzigste","einundzwanzigsten","21st"],["22","zweiundzwanzigste","zweiundzwanzigsten","22nd"],["23","dreiundzwanzigste","dreiundzwanzigsten","23rd"],["24","vierundzwanzigste","vierundzwanzigsten","24th"],["25","fünfundzwanzigste","fünfundzwanzigsten","25th"],["26","sechsundzwanzigste","sechsundzwanzigsten","26th"],["27","siebenundzwanzigste","siebenundzwanzigsten","27th"],["28","achtundzwanzigste","achtundzwanzigsten","28th"],["29","neunundzwanzigste","neunundzwanzigsten","29th"],["30","dreißigste","dreißigsten","30th"],["31","einunddreißigste","einunddreißigsten","31st"]],"highlight_row":-1,"description_de":"Der Wievielte ist heute? — Heute ist der fünfte Mai. Bis 19 meist -te (aber erste, dritte, siebte, achte sind unregelmäßig!). Ab 20 immer -ste. Mit der: Endung -e (der fünfte). Mit am: Endung -en (am fünften).","description_en":"Der Wievielte ist heute? — Heute ist der fünfte Mai. (What is the date today? — Today is May 5th.) Up to 19, add -te (but erste, dritte, siebte and achte are irregular!). From 20 on, always add -ste. With der: use the -e ending (der fünfte). With am: use the -en ending (am fünften)."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'db4b344f-55c9-55ca-9358-733268fce5dc'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '2c0ae29f-c7b1-5449-9e73-b5edf88b8f81'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'pattern', 'How to Say a Colloquial Time', 'So sagst du die Uhrzeit umgangssprachlich', '{"type":"steps","steps":[{"step":1,"title_de":"Ist es genau :30? → halb + NÄCHSTE Stunde","title_en":"Is it exactly :30? → halb + the NEXT hour","detail_de":"2:30 → halb drei (nicht halb zwei!). 5:30 → halb sechs. 8:30 → halb neun.","detail_en":"For X:30, say halb + the NEXT hour, never the current one. 2:30 → halb drei. 5:30 → halb sechs. 8:30 → halb neun."},{"step":2,"title_de":"Ist es :15 oder :45? → Viertel nach / Viertel vor","title_en":"Is it :15 or :45? → Viertel nach / Viertel vor","detail_de":"X:15 = Viertel nach + aktuelle Stunde (2:15 = Viertel nach zwei). X:45 = Viertel vor + NÄCHSTE Stunde (2:45 = Viertel vor drei).","detail_en":"X:15 = Viertel nach + the current hour (2:15 = Viertel nach zwei). X:45 = Viertel vor + the NEXT hour (2:45 = Viertel vor drei)."},{"step":3,"title_de":"Sonst: Minutenzahl + nach / vor","title_en":"Otherwise: minute number + nach / vor","detail_de":"Vor der halben Stunde: Minuten + nach (2:05 = fünf nach zwei; 2:20 = zwanzig nach zwei). Nach der halben Stunde: Minuten bis zur nächsten Stunde + vor (2:50 = zehn vor drei).","detail_en":"Before the half hour: minutes + nach (2:05 = fünf nach zwei; 2:20 = zwanzig nach zwei). After the half hour: minutes remaining to the next hour + vor (2:50 = zehn vor drei)."}],"description_de":"Drei Schritte, um jede Uhrzeit umgangssprachlich zu sagen.","description_en":"Three steps to say any time in colloquial German."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '2c0ae29f-c7b1-5449-9e73-b5edf88b8f81'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '357f3a5f-531f-5028-938a-be1cc3def3ca'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'warning', 'The Classic Trap: halb drei', 'Die klassische Falle: halb drei', '{"content_de":"halb drei bedeutet 2:30, nicht 3:30! Denk an halb als ''auf dem Weg zur nächsten Stunde'', nicht als ''halb nach dieser Stunde''.","content_en":"halb drei means 2:30, not 3:30! Think of halb as ''halfway TO the next hour'', not ''half past this hour''."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '357f3a5f-531f-5028-938a-be1cc3def3ca'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '63b86371-bb80-5f01-9579-3e3d0cecb388'::uuid, '3101f292-4ef6-5f64-884c-6703f436e109'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Offiziell (24 Stunden): vierzehn Uhr dreißig = 14:30. Umgangssprachlich (12 Stunden): halb drei = 2:30.","halb + NÄCHSTE Stunde: halb drei = 2:30, nicht 3:30!","Viertel nach zwei = 2:15. Viertel vor drei = 2:45.","Wann? am + Wochentag (am Montag), um + Uhrzeit (um acht Uhr), im + Monat (im Mai) — Ausnahme: in der Nacht.","Sieben Wochentage, sechs Tageszeiten: am Morgen, am Vormittag, am Mittag, am Nachmittag, am Abend, in der Nacht.","Das Datum: Der Wievielte ist heute? — Heute ist der fünfte Mai. Wann? — Am fünften Mai.","Unregelmäßige Ordnungszahlen: erste, dritte, siebte, achte."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '63b86371-bb80-5f01-9579-3e3d0cecb388'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '8d0b0e94-1ee7-5cf5-a0fa-d8f8aa1abf28'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Das ist mein Bruder.', 'That is my brother.', 'mein', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Bruder is masculine → mein, no ending.', 'Bruder ist maskulin → mein, keine Endung.', '{"Das":"that","ist":"is","mein":"my (masculine)","Bruder":"brother"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '8d0b0e94-1ee7-5cf5-a0fa-d8f8aa1abf28'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '68b141b7-942a-5ae1-839d-bc8fa4b13847'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Meine Schwester ist Ärztin.', 'My sister is a doctor.', 'Meine', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Schwester is feminine → meine (mein + e).', 'Schwester ist feminin → meine.', '{"Meine":"my (feminine)","Schwester":"sister","ist":"is","Ärztin":"doctor"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '68b141b7-942a-5ae1-839d-bc8fa4b13847'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '40014a2d-5e8d-5352-a1dc-86559c3502e1'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Wie heißt dein Vater?', 'What is your father''s name?', 'dein', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Vater is masculine → dein.', 'Vater ist maskulin → dein.', '{"Wie":"how","heißt":"is called","dein":"your (masculine)","Vater":"father"}'::jsonb, 1, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '40014a2d-5e8d-5352-a1dc-86559c3502e1'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4361426a-6f6e-5c54-923d-228d09dfb47b'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Sein Handy ist neu.', 'His phone is new.', 'Sein', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'Handy is neuter → sein, same form as masculine.', 'Handy ist neutral → sein.', '{"Sein":"his (neuter)","Handy":"phone","ist":"is","neu":"new"}'::jsonb, 1, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4361426a-6f6e-5c54-923d-228d09dfb47b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'b5cb8d17-96f0-503e-920a-28c45948c117'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Das Kind hat sein Buch.', 'The child has its book.', 'sein', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'sein can also mean its, when the owner is a das-word like Kind.', 'sein kann auch its bedeuten, wenn der Besitzer ein das-Wort wie Kind ist.', '{"Das":"the","Kind":"child","hat":"has","sein":"its (neuter)","Buch":"book"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'b5cb8d17-96f0-503e-920a-28c45948c117'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '56b0ff6f-b4a4-5b87-9b1b-bc5634c102e9'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Das ist ihre Wohnung.', 'That is her apartment.', 'ihre', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wohnung is feminine → ihre (ihr + e). Here ihr refers to sie (she).', 'Wohnung ist feminin → ihre. ihr bezieht sich hier auf sie (Einzahl).', '{"Das":"that","ist":"is","ihre":"her (feminine)","Wohnung":"apartment"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '56b0ff6f-b4a4-5b87-9b1b-bc5634c102e9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'd9410409-62e4-5677-bd49-8dd2ee65f4c0'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Die Eltern lieben ihre Kinder.', 'The parents love their children.', 'ihre', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'Kinder is plural → ihre (ihr + e). Here ihr refers to sie (they) — the parents.', 'Kinder ist Plural → ihre. ihr bezieht sich hier auf sie (Plural) — die Eltern.', '{"Die":"the","Eltern":"parents","lieben":"love","ihre":"their (plural)","Kinder":"children"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'd9410409-62e4-5677-bd49-8dd2ee65f4c0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '2e4dfc2e-2915-5406-a43e-06d7fa610dc4'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Wir lieben unser Land.', 'We love our country.', 'unser', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'Land is neuter → unser, no ending.', 'Land ist neutral → unser.', '{"Wir":"we","lieben":"love","unser":"our (neuter)","Land":"country"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '2e4dfc2e-2915-5406-a43e-06d7fa610dc4'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'eeceed37-c0a5-5930-a91b-c2a3944c2880'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Wie heißt eure Lehrerin?', 'What is your (plural) teacher''s name?', 'eure', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'euer drops its e before an ending: eure, not euere. Lehrerin is feminine → eure.', 'euer verliert das e vor einer Endung: eure, nicht euere.', '{"Wie":"how","heißt":"is called","eure":"your (plural, feminine noun)","Lehrerin":"teacher (female)"}'::jsonb, 2, 'everyday'
