INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4008151b-c0fc-5e89-b84f-9cc1a0a36cd2'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 'Ist das Ihr Schlüssel?', 'Is that your key? (formal)', 'Ihr', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ihr (capital I) = formal your. Schlüssel is masculine → Ihr, no ending.', 'Ihr (großes I) = Höflichkeitsform. Schlüssel ist maskulin → Ihr, keine Endung.', '{"Ist":"is","das":"that","Ihr":"your (formal, masculine noun)","Schlüssel":"key"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4008151b-c0fc-5e89-b84f-9cc1a0a36cd2'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ba0a9b7c-12bf-5ef0-9a7a-1e5149e9ceb3'::uuid, 'd1cbc951-728b-5dcc-a370-0c10fba7d118'::uuid, 'Ich stehe um 7 Uhr auf.', 'I get up at 7 o''clock.', 'stehe … auf', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'aufstehen splits: stehe stays in position 2, auf goes to the end.', 'aufstehen trennt sich: stehe steht auf Position 2, auf steht am Ende.', '{"7":"7","Ich":"I","stehe":"get up (stem)","um":"at","Uhr":"o''clock","auf":"up (prefix, end)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ba0a9b7c-12bf-5ef0-9a7a-1e5149e9ceb3'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
