WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd9887d31-0932-5143-b05e-3f903d659cd9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '56dc459e-5c31-51fb-bd2f-799a23046228'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', '___ Schwester ist Ärztin. (ich)', 'My sister is a doctor. (owner: ich)', NULL, 'Meine', '["Meine","meine"]'::jsonb, 'Schwester is feminine (die-word) → meine (mein + e).', 'Schwester ist feminin (die-Wort) → meine.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich → mein + e (feminine noun) = meine.', 'ich → mein + e (feminines Nomen) = meine.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '56dc459e-5c31-51fb-bd2f-799a23046228'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '46ae02ff-1593-5d9e-9956-bc9fb215b015'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', '___ Auto ist neu. (er)', 'His car is new. (owner: er)', NULL, 'Sein', '["Sein","sein"]'::jsonb, 'Auto is neuter (das-word) → sein, no ending — same as masculine.', 'Auto ist neutral (das-Wort) → sein, keine Endung.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'er → sein. Auto = das-word → no ending needed.', 'er → sein. Auto = das-Wort → keine Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '46ae02ff-1593-5d9e-9956-bc9fb215b015'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3bc06ffd-69f5-52b2-bb90-9c38dce7128b'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', 'Das ist ___ Tasche. (sie, Einzahl)', 'That is her bag. (owner: she)', NULL, 'ihre', '["ihre"]'::jsonb, 'Tasche is feminine → ihre (ihr + e). Here ihr means her.', 'Tasche ist feminin → ihre. ihr bedeutet hier her (sie, Einzahl).', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sie (she) → ihr + e (feminine noun) = ihre.', 'sie (Einzahl) → ihr + e (feminines Nomen) = ihre.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3bc06ffd-69f5-52b2-bb90-9c38dce7128b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '210e89f8-2c89-5897-a247-a9bd3d84e4ae'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', 'Die Eltern lieben ___ Kinder. (sie, Plural)', 'The parents love their children. (owner: sie, plural = they)', NULL, 'ihre', '["ihre"]'::jsonb, 'Kinder is plural → ihre (ihr + e). Here ihr means their.', 'Kinder ist Plural → ihre. ihr bedeutet hier their (sie, Plural).', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sie (they) → ihr + e (plural noun) = ihre.', 'sie (Plural) → ihr + e (Plural-Nomen) = ihre.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '210e89f8-2c89-5897-a247-a9bd3d84e4ae'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fbf09b8d-ea92-56fa-b89d-870d2ddfda54'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'multiple_choice', 'Wie heißt ___ Mutter? (ihr, Plural = you all)', 'What is your (you-all) mother''s name? (owner: ihr, plural you)', '["eure","euere","unsere","ihre"]'::jsonb, 'eure', NULL, 'euer drops its e before an ending: eure, not euere.', 'euer verliert das e vor einer Endung: eure, nicht euere.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Mutter is feminine → euer + e, but the e in euer drops → eure.', 'Mutter ist feminin → euer + e, aber das e in euer fällt weg → eure.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fbf09b8d-ea92-56fa-b89d-870d2ddfda54'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3350c4ae-d08b-5a28-8e66-3cb273f39b5e'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', 'Wir lieben ___ Land. (wir)', 'We love our country. (owner: wir)', NULL, 'unser', '["unser"]'::jsonb, 'Land is neuter → unser, no ending.', 'Land ist neutral → unser, keine Endung.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'wir → unser. Land = das-word → no ending needed.', 'wir → unser. Land = das-Wort → keine Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3350c4ae-d08b-5a28-8e66-3cb273f39b5e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a85206a6-d5c3-5a86-8695-bfe661b1dd20'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', 'Wo ist ___ Schlüssel? (du)', 'Where is your key? (owner: du)', NULL, 'dein', '["dein"]'::jsonb, 'Schlüssel is masculine → dein, no ending.', 'Schlüssel ist maskulin → dein, keine Endung.', NULL, 8, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'du → dein. Schlüssel = der-word → no ending needed.', 'du → dein. Schlüssel = der-Wort → keine Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a85206a6-d5c3-5a86-8695-bfe661b1dd20'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '025bbe17-3ad0-5282-a408-4dab49be3095'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'multiple_choice', 'Welche Frage ist die Höflichkeitsform?', 'Which question uses the formal (Sie) form?', '["Wie ist dein Name?","Wie ist sein Name?","Wie ist Ihr Name?","Wie ist euer Name?"]'::jsonb, 'Wie ist Ihr Name?', NULL, 'Formal address uses Sie/Ihr (always capitalized).', 'Die Höflichkeitsform benutzt Sie/Ihr (immer großgeschrieben).', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'A stranger is addressed formally with Sie, so the possessive is Ihr.', 'Ein Fremder wird mit Sie angesprochen, also lautet der Possessivartikel Ihr.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '025bbe17-3ad0-5282-a408-4dab49be3095'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b269d424-9f5f-5bfc-9703-50b0c0b5e5a4'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'multiple_choice', 'Ist das ___ Adresse? (Sie, Höflichkeitsform)', 'Is that your address? (formal, owner: Sie)', '["Ihre","Ihr","seine","eure"]'::jsonb, 'Ihre', NULL, 'Adresse is feminine → Ihre, the formal possessive for Sie. Ihr has no ending (wrong for a feminine noun); seine and eure belong to different owners.', 'Adresse ist feminin → Ihre, der Possessivartikel für Sie. Ihr hat keine Endung (falsch für ein feminines Nomen); seine und eure gehören zu anderen Besitzern.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Owner is Sie (formal) and Adresse is feminine → Ihre is the only option that matches both owner and gender.', 'Besitzer ist Sie (Höflichkeitsform) und Adresse ist feminin → nur Ihre passt zu Besitzer und Genus.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b269d424-9f5f-5bfc-9703-50b0c0b5e5a4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '48bbb8f0-2b0f-512f-a7df-04f8e6f43e0f'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'multiple_choice', 'Was ist richtig? Der Besitzer ist er, das Nomen ist Schwester.', 'Which is correct? The owner is ''he'', the noun is ''sister'' (feminine).', '["sein Schwester","seine Schwester","ihre Schwester","ihr Schwester"]'::jsonb, 'seine Schwester', NULL, 'Schwester is feminine → the ending -e is required: seine, even though the owner is male.', 'Schwester ist feminin → die Endung -e ist nötig: seine, auch wenn der Besitzer männlich ist.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The noun''s gender (feminine) decides the ending, not the owner''s gender.', 'Das Genus des Nomens (feminin) entscheidet die Endung, nicht das Geschlecht des Besitzers.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '48bbb8f0-2b0f-512f-a7df-04f8e6f43e0f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5873db19-6dab-5743-90a8-96231f8fa992'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'fill_blank', 'Wie heißt ___ Lehrerin? (ihr, Plural = you all)', 'What is your (you-all) teacher''s name? (owner: ihr, plural you)', NULL, 'eure', '["eure"]'::jsonb, 'Lehrerin is feminine → euer + e, but the e in euer drops → eure.', 'Lehrerin ist feminin → euer + e, aber das e fällt weg → eure.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr (you all) → euer + e (feminine noun), e drops → eure.', 'ihr (Plural) → euer + e (feminines Nomen), e fällt weg → eure.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5873db19-6dab-5743-90a8-96231f8fa992'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '41e1c650-118c-58a1-a6a9-ec54e540808c'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 4, 'multiple_choice', 'Das Kind hat ___ Buch. (es)', 'The child has its book. (owner: es)', '["sein","seine","ihr","Ihre"]'::jsonb, 'sein', NULL, 'Buch is neuter → sein, no ending. es (it) uses sein, same as er.', 'Buch ist neutral → sein, keine Endung. es benutzt sein, genauso wie er.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'es → sein. Buch = das-word → no ending needed.', 'es → sein. Buch = das-Wort → keine Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '41e1c650-118c-58a1-a6a9-ec54e540808c'::uuid);

