SELECT '388af6b1-9be8-5418-9d0f-1480baaa31b0'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 5, 'fill_blank', '___ Freundin wohnt in Berlin. (ich)', 'My girlfriend lives in Berlin. (owner: ich)', NULL, 'Meine', '["Meine","meine"]'::jsonb, 'Freundin is feminine → meine.', 'Freundin ist feminin → meine.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich → mein + e (feminine noun) = meine.', 'ich → mein + e (feminines Nomen) = meine.', NULL
