INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '10b25f5c-723f-58dc-b4fb-6a5b5826e352'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 5, 'multiple_choice', 'Wie ist ___ Name, bitte? (Sie, Höflichkeitsform)', 'What is your name, please? (formal, owner: Sie)', '["Ihr","Ihre","sein","euer"]'::jsonb, 'Ihr', NULL, 'Name is masculine → Ihr, the formal possessive for Sie, with no ending. Ihre would need a feminine or plural noun; sein and euer belong to different owners.', 'Name ist maskulin → Ihr, der Possessivartikel für Sie, ohne Endung. Ihre bräuchte ein feminines oder Plural-Nomen; sein und euer gehören zu anderen Besitzern.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Owner is Sie (formal) and Name is masculine → Ihr is the only option that matches both owner and gender.', 'Besitzer ist Sie (Höflichkeitsform) und Name ist maskulin → nur Ihr passt zu Besitzer und Genus.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '10b25f5c-723f-58dc-b4fb-6a5b5826e352'::uuid);

