SELECT '48df1e8d-2503-5a15-a985-e479c9f73dea'::uuid, '4b9de34e-e09d-55e9-bb53-9cb3e3a692c5'::uuid, 5, 'multiple_choice', 'Wie sagt man ''my key'' auf Deutsch? (Schlüssel = der-Wort)', 'How do you say ''my key'' in German? (Schlüssel is masculine)', '["mein Schlüssel","meine Schlüssel","sein Schlüssel","meinen Schlüssel"]'::jsonb, 'mein Schlüssel', NULL, 'Schlüssel is masculine, Nominativ → mein, no ending.', 'Schlüssel ist maskulin, Nominativ → mein, keine Endung.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Owner is ich, noun is masculine → mein with no ending.', 'Besitzer ist ich, Nomen ist maskulin → mein ohne Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '48df1e8d-2503-5a15-a985-e479c9f73dea'::uuid);

